def backfill_cashshift_actor_snapshots(apps, schema_editor):
    """Cashier/locator names must survive the account that created the shift.

    `CashShift.cashier` and `CashShift.owner` now detach (SET_NULL) so an account
    with nothing but a cash shift can be permanently deleted. Any shift that does
    survive needs a readable name in its ledger, so fill the snapshots here.
    """
    CashShift = apps.get_model("inventory", "CashShift")
    User = apps.get_model(*settings.AUTH_USER_MODEL.split("."))

    usernames = dict(User.objects.values_list("id", "username"))
    for shift in CashShift.objects.all().only("id", "cashier_id", "owner_id"):
        updates = {}
        if not shift.cashier_username and shift.cashier_id in usernames:
            updates["cashier_username"] = usernames[shift.cashier_id]
        if updates:
            CashShift.objects.filter(id=shift.id).update(**updates)


